    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_highest_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        sorted_bids = sorted(yesterday_bids, reverse=True)
        second_highest_prev_bid = sorted_bids[1]

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    # If I'm in danger, bid aggressively but cap to avoid bankrupting.
    if my_hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * 0.85
        return max(0.0, min(my_budget, target))

    # Otherwise, match/just beat the strongest signal from yesterday.
    # Bob/Cindy were strong; we aim slightly above upper-mid rather than absolute max.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If they were really bidding hard, we shade above the second-highest to win
        # without paying the absolute maximum.
        target = max(DAILY_SALARY * 0.28, second_highest_prev_bid + 2.0)
    else:
        # Moderate pressure: bid around half salary or just above their top.
        target = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

    # Supply-based slight adjustment: with higher supply, we can bid a bit less.
    # Ensure list indices are not used; simple arithmetic only.
    if supply >= 22.0:
        target *= 0.92
    elif supply <= 16.0:
        target *= 1.05

    # Final clamp
    return max(0.0, min(my_budget, target))

