    elif danger >= 4:
        bid = max(DAILY_SALARY * 0.72, target_prev + 1.5)
    elif tight:
        bid = max(DAILY_SALARY * 0.52, target_prev + 1.0)
    else:
        bid = max(DAILY_SALARY * 0.38, target_prev * 0.78 + 1.0)

